    }

    pub fn sequenceBegin(self: *_dec_Example, id: sofab.Id) void {
        if (self.sp < self.stack.len) {
            self.stack[self.sp] = self.cur;
            self.sp += 1;
        }
        self.cur = switch (self.cur) {
            .root => switch (id) {
                10 => .root_nested,
                100 => .root_arrays,
                200 => blk: { self.m.string_array = &.{}; break :blk .root_string_array; },
                else => .dead,
            },
            .root_arrays => switch (id) {
                10 => .root_arrays_nested,
                else => .dead,
            },
            else => .dead,
        };
    }

    pub fn sequenceEnd(self: *_dec_Example) void {
        if (self.sp > 0) {
            self.sp -= 1;
            self.cur = self.stack[self.sp];
        } else {
            self.cur = .root;
        }
    }
};
